    std::string initialsOf(const char *syllable) {
        return cpp_pinyin::v2::u16strToUtf8str(
            cpp_pinyin::v2::ManTone::toneToInitials(cpp_pinyin::v2::utf8strToU16str(syllable)));
    }

    std::string finalsOf(const char *syllable, const bool vToU = false) {
        return cpp_pinyin::v2::u16strToUtf8str(
            cpp_pinyin::v2::ManTone::toneToFinals(cpp_pinyin::v2::utf8strToU16str(syllable), vToU));
    }

    std::string finals3Of(const char *syllable, const bool vToU = false, const bool neutral5 = false) {
        return cpp_pinyin::v2::u16strToUtf8str(
            cpp_pinyin::v2::ManTone::toneToFinals3(cpp_pinyin::v2::utf8strToU16str(syllable), vToU, neutral5));
    }

